  ('pz-daa-bfs', 'traversal', 100, 'puzzle', 'Breadth-first search, by hand.', null, '{"type":"bfs","nodes":7,"extra":3}'::jsonb, 'Keep a queue. Take the vertex at the front and add its unvisited neighbours in alphabetical order.', 'Mixed up BFS and DFS order', null, '{}'::jsonb, ''),
  ('pz-daa-dfs', 'traversal', 101, 'puzzle', 'Depth-first search, by hand.', null, '{"type":"dfs","nodes":7,"extra":3}'::jsonb, 'Go to the alphabetically first unvisited neighbour. At a dead end, back up to the last vertex that still has one.', 'Mixed up DFS and BFS order', null, '{}'::jsonb, ''),
  ('pz-daa-topo', 'topological', 102, 'puzzle', 'Topological sort, by hand.', null, '{"type":"topo","nodes":6}'::jsonb, 'Pick any vertex that no remaining arrow points into, then remove it and its arrows.', 'Placed a vertex before one of its prerequisites', null, '{}'::jsonb, ''),
  ('pz-daa-dijkstra', 'dijkstra', 103, 'puzzle', 'Run Dijkstra''s algorithm.', null, '{"type":"dijkstra","nodes":6,"extra":4}'::jsonb, 'Track the best known distance to each vertex. Always finalise the unfinished vertex with the smallest one.', 'Finalised a vertex before its shortest distance was known', null, '{}'::jsonb, ''),
  ('pz-daa-shortest', 'shortest', 104, 'puzzle', 'Shortest paths from one source.', null, '{"type":"dijkstra","nodes":7,"extra":5}'::jsonb, 'A vertex''s distance is final once it''s the smallest among the unfinished vertices; then relax its edges.', 'Finalised a vertex before its shortest distance was known', null, '{}'::jsonb, ''),
  ('pz-daa-kruskal', 'mst', 105, 'puzzle', 'Build a minimum spanning tree with Kruskal''s algorithm.', null, '{"type":"kruskal","nodes":6,"extra":4}'::jsonb, 'Sort the edges by weight. Take the cheapest edge that doesn''t close a cycle.', 'Took an edge that closes a cycle, or not the cheapest', null, '{}'::jsonb, ''),
  ('pz-daa-hamilton', 'hamiltonian', 106, 'puzzle', 'Find a Hamiltonian cycle by backtracking.', null, '{"type":"hamiltonian","nodes":7}'::jsonb, 'Prefer vertices with few edges left: they''re easiest to get stranded at. Step back as soon as a branch is a dead end.', 'Couldn''t backtrack to a Hamiltonian cycle', null, '{}'::jsonb, ''),
  ('pz-daa-selection', 'sorting', 107, 'puzzle', 'Play selection sort.', null, '{"type":"selection-sort","size":7}'::jsonb, 'Scan the whole unsorted part (the bars not yet green) and find its smallest value.', 'Didn''t pick the minimum of the unsorted part', null, '{}'::jsonb, ''),
  ('pz-daa-bst', 'trees', 108, 'puzzle', 'Search a binary search tree.', null, '{"type":"bst-search","nodes":9}'::jsonb, 'Start at the root. Smaller keys are always to the left, larger ones to the right.', 'Didn''t follow the BST search path', null, '{}'::jsonb, ''),
  ('pz-daa-queens', 'paradigms', 109, 'puzzle', 'Backtracking: the N-Queens problem.', null, '{"type":"queens","n":6}'::jsonb, 'Place one queen per row. When a row has no safe square, move the queen in the row above.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-maze', 'ds-maze', 110, 'puzzle', 'Escape the maze.', null, '{"type":"maze","size":7}'::jsonb, 'At every junction try one way; at a dead end go back to the last junction with an untried corridor.', 'Lost the way in the maze', null, '{}'::jsonb, ''),
  ('pz-ds-queens', 'ds-backtracking', 111, 'puzzle', 'Backtracking: place the queens.', null, '{"type":"queens","n":5}'::jsonb, 'Go row by row. If a row has no safe square left, go back one row and move that queen on.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-queens-8', 'ds-backtracking', 112, 'puzzle', 'The classic eight queens.', null, '{"type":"queens","n":8}'::jsonb, 'Go row by row. If a row has no safe square left, go back one row and move that queen on.', 'Placed queens that attack each other', null, '{}'::jsonb, ''),
  ('pz-ds-hanoi-3', 'ds-hanoi', 113, 'puzzle', 'Tower of Hanoi with three disks.', null, '{"type":"hanoi","disks":3}'::jsonb, 'With an odd number of disks, the smallest disk''s first move goes straight to the target peg.', 'Used more moves than needed', null, '{}'::jsonb, ''),
